import std;
import openmui.simulation;
import openmui.simulation.cellular;
namespace ca=omui::simulation::cellular;
struct Model {
 struct State {ca::Program program;std::vector<std::uint32_t> a,b;bool ok=true;};
 struct Input {bool unused=false;};
 static void step(State& s,const Input&) {s.ok=bool(s.program.step({7,3},s.a,s.b,{.tile={2,2},.boundary={ca::Edge::wrap}}));s.a.swap(s.b);}
};
int main() {
 const std::array rules{ca::Rule{{},{{0,ca::WriteKind::add_saturating,1}}}};
 auto program=ca::Program::prepare(1,rules);if(!program)return 1;
 omui::simulation::Timeline<Model> history({*program,std::vector<std::uint32_t>(21),std::vector<std::uint32_t>(21)},30,3);
 for(int i=0;i<20;++i)history.step({});
 for(int f:{20,1,13,0,19}) {if(!history.seek(f) || !history.state().ok)return 2;for(auto x:history.state().a)if(x!=static_cast<unsigned>(f))return 3;}
 std::println("{{\"kind\":\"simulation.consumer\",\"ok\":true,\"steps\":20,\"queries\":5}}");
}
